mapper.update:
UPDATE crm_quote SET contract_id = #{record.contractId}, contract_no = #{record.contractNo}, version = version + 1,
    update_by = #{record.updateBy}, update_time = #{record.updateTime}
WHERE quote_id = #{record.quoteId} AND tenant_id = #{record.tenantId} AND deleted = 0 AND contract_id IS NULL AND version = #{expectedVersion}

UPDATE crm_quote SET status = 'ACCEPTED', version = version + 1, update_by = #{record.updateBy}, update_time = #{record.updateTime}
WHERE quote_id = #{record.quoteId} AND tenant_id = #{record.tenantId} AND deleted = 0 AND contract_id = #{record.contractId}
    AND status IN ('APPROVED', 'SENT') AND version = #{expectedVersion}

UPDATE crm_quote SET owner_id = #{record.ownerId}, owner_name = #{record.ownerName},
    version = version + 1, update_by = #{record.updateBy}, update_time = #{record.updateTime}
WHERE quote_id = #{record.quoteId} AND tenant_id = #{record.tenantId} AND version = #{expectedVersion} AND deleted = 0

mapper.select:
SELECT t.quote_id, t.tenant_id, t.instance_id, t.quote_no, t.customer_id, t.customer_name, t.opportunity_id, t.opportunity_name, t.quote_name, t.total_amount, t.tax_amount, t.currency, t.version, AS currency_locked, t.valid_until, t.owner_id, t.owner_name, t.contract_id, t.contract_no, t.attachment_url, t.remark, t.status, t.deleted, t.create_by, t.create_time, t.update_by, t.update_time, c.dept_id AS scope_dept_id, c.owner_id AS scope_owner_id FROM crm_quote t INNER JOIN crm_customer c ON c.customer_id = t.customer_id AND c.deleted = '0' WHERE t.deleted = '0'
AND t.customer_id = #{query.customerId}
AND t.opportunity_id = #{query.opportunityId}
AND t.quote_name LIKE CONCAT('%', #{query.quoteName}, '%')
AND t.status = #{query.status}
ORDER BY t.update_time DESC
